-- What a run read, so the next run can tell a provider's full list from a broken one (ADR-006): whether the list
-- was complete and passed the checks, how many of its records were seen (saved, or skipped only for their venue),
-- and how many each part of the provider (a Karabas section) listed. Runs before this migration count as not
-- complete.
ALTER TABLE "import_runs"
    ADD COLUMN "complete" BOOLEAN NOT NULL DEFAULT false,
    ADD COLUMN "seen" INTEGER,
    ADD COLUMN "parts" JSONB;
